  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Molecule 1 (linezolid) had an absolute oral bioavailability of 88.4% in elderly hospitalized patients, well above the 20% threshold."
    },
    {
      "card_ids": ["C32"],
      "claim": "Molecule 3 (suvorexant) had a mean absolute oral bioavailability of 82% under fasted conditions, directly supporting high bioavailability."
    },
    {
      "card_ids": ["C39"],
      "claim": "Molecule 9 (lurasidone) had 10% oral bioavailability in the fasted state, below the 20% threshold and supporting low bioavailability."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C39"],
  "decision_summary": "Multiple high-transferability molecules with absolute or ordinary-condition oral bioavailability values of 82-88% support high bioavailability, outweighing one fasted-state low value of 10%. Confidence is moderate because of this single contradictory high-transferability record and some provenance/qualitative gaps.",
  "evidence_gaps": [
    "Molecule 2 records conflate brigatinib and GSK1322322; these inconsistent cards were discounted as a provenance conflict.",
    "Molecule 8 provides only qualitative 'good' oral bioavailability without a numeric threshold-relevant value."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C02", "C32"],
  "revision_action": "initial",
  "supportive_card_ids": ["C02", "C32"]
}

